1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.CityRegion;
5	import org.springframework.samples.petclinic.model.CustomerCode;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.model.RegionPostcodes;
8	
9	/**
10	 * Assigns a newly built owner its {@code customerCode}, formatted {@code <REGION>-<HASH8>}: REGION is
11	 * the region code derived from the owner's postcode (falling back to its city, else
12	 * {@link CityRegion#UNKNOWN}) and HASH8 is the first 8 upper-case hex characters of SHA-256 over the
13	 * normalized telephone followed by the last name (e.g. {@code NSW-1A2B3C4D}). See
14	 * {@link CustomerCode}. Runs after the telephone has been normalized so the hash covers the stored
15	 * E.164 value.
16	 */
17	public class AssignCustomerCode {
18	
19	    public void service(@Val Owner owner) {
20	        String region = region(owner);
21	        owner.setCustomerCode(CustomerCode.of(region, owner.getTelephone(), owner.getLastName()));
22	    }
23	
24	    /** The owner's region: derived from the postcode, else the city, else {@link CityRegion#UNKNOWN}. */
25	    private static String region(Owner owner) {
26	        String byPostcode = RegionPostcodes.regionOf(owner.getPostcode());
27	        return byPostcode != null ? byPostcode : CityRegion.of(owner.getCity());
28	    }
29	}
