1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Membership;
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.util.StringUtils;
7	
8	/**
9	 * Scores a newly built owner: assigns its {@code membershipPoints} from the loyalty factors in
10	 * {@link Membership} and the {@code membershipLevel} those points map to. A newly created owner has
11	 * no tenure yet, so the tenure points never apply here and the level never exceeds 3. Runs after
12	 * {@link CountNamesakes} and {@link CountHouseholdMembers} so the namesake count and household size
13	 * are set, and before {@link CapMembershipLevel}, which then bounds the assigned level by the owner's
14	 * household.
15	 */
16	public class AssignMembership {
17	
18	    /** A newly created owner has not yet accrued any tenure (zero elapsed fiscal years). */
19	    private static final long TENURE_AT_CREATION = 0;
20	
21	    public void service(@Val Owner owner) {
22	        int points = Membership.points(StringUtils.hasText(owner.getEmail()), owner.getNamesakeCount(),
23	            owner.getHouseholdSize(), TENURE_AT_CREATION);
24	        owner.setMembershipPoints(points);
25	        owner.setMembershipLevel(Membership.levelFor(points));
26	    }
27	}
