9	/**
10	 * Caps a newly scored owner's {@code membershipLevel} at one above the current maximum level among the
11	 * existing members of its household, so a new member cannot leapfrog their household's standing. Runs
12	 * after {@link AssignMembership} has scored the owner and keys off the same existing household members
13	 * as {@link CountHouseholdMembers}. With no existing household member (a new or single-owner household)
14	 * no ceiling applies and the assigned level stands.
15	 */
16	public class CapMembershipLevel {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        OptionalInt maxLevel = Household.existingMembers(owner, ownerRepository).stream()
20	            .map(Owner::getMembershipLevel)
21	            .filter(level -> level != null)
22	            .mapToInt(Integer::intValue)
23	            .max();
24	        if (maxLevel.isEmpty()) {
25	            return;
26	        }
27	        int ceiling = maxLevel.getAsInt() + 1;
28	        if (owner.getMembershipLevel() > ceiling) {
29	            owner.setMembershipLevel(ceiling);
30	        }
31	    }
32	}
